{name:"pages/0901.md"};function n(d,t,c,h,p,s){return a(),r("div",null,[...t[0]||(t[0]=[o('<div class="doc-eyebrow">指标与行情 / CHATTRADE KNOWLEDGE BASE</div><h1 id="指标-ide-与社区" tabindex="-1">指标 IDE 与社区 <a class="header-anchor" href="#指标-ide-与社区" aria-label="Permalink to &quot;指标 IDE 与社区&quot;">​</a></h1><div class="doc-lead">指标用于图表可视化；社区用于发现与复用指标。</div><h2 id="指标-ide" tabindex="-1">指标 IDE <a class="header-anchor" href="#指标-ide" aria-label="Permalink to &quot;指标 IDE&quot;">​</a></h2><p><code>/indicator-ide</code> 用于编写图表指标（可视化），与 Strategy IDE 的可执行策略脚本不同。指标代码服务画线与标记，不应被描述为自动下单逻辑。</p><h2 id="指标社区" tabindex="-1">指标社区 <a class="header-anchor" href="#指标社区" aria-label="Permalink to &quot;指标社区&quot;">​</a></h2><p><code>/indicator-community</code>（桌面）与手机 <code>/market</code> 提供浏览、详情与已购内容。购买或安装指标只影响图表能力，不自动授权策略实盘资金。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>把“指标信号”当成交易指令前，必须经过策略/执行模块与账户风控。图表刷新失败时，先检查行情源与登录态，再判断指标脚本本身是否报错。</p>',9)])])}const m=e(i,[["render",n]]);export{g as __pageData,m as default};
